const char *Q_NAME = "/temp_data_queue";
int ret_val;

// Removes the name immediately. Queue destroyed upon
// final close() by all open processes.
ret_val = mq_unlink(Q_NAME);

if (ret_val == -1) {
    // ENOENT: Queue name does not exist.
    // EACCES: Permission denied.
    perror("mq_unlink error");
} else {
    // Successfully unlinked name
}
